<template>
  <div class="cw" :style="brand">
    <header class="cw-header"><div><span class="cw-eyebrow">{{ operatorName }} · Credentialing operations</span><h1>Credentialing Management</h1><p>Provider credentials, agency group NPIs, and payer connections across your authorized agencies.</p></div><div class="cw-buttons"><button @click="load" :disabled="loading">Refresh</button><button class="primary" :disabled="scope === 'all'" @click="openRecords(Number(scope))">Add / manage enrollment</button></div></header>
    <section class="cw-toolbar" aria-label="Credentialing filters"><label>Organization scope<select v-model="scope" data-testid="credential-scope"><option value="all">All authorized agencies</option><option v-for="agency in organizations" :key="agency.id" :value="String(agency.id)">{{ agency.name }}</option></select></label><label class="cw-search">Search<input v-model="search" placeholder="Provider, agency, NPI, payer or next action…" /></label><label>Status<select v-model="status"><option value="all">All statuses</option><option value="open">Open credentialing work</option><option v-for="item in statuses" :key="item" :value="item">{{ label(item) }}</option><option value="verification_needed">Verification needed</option></select></label></section>
    <p v-if="error" class="cw-error" role="alert">{{ error }}</p><p v-if="notice" role="status" class="cw-notice">{{ notice }}</p><p v-if="loading" role="status">Loading credentialing records…</p>
    <template v-if="!loading && loaded">
      <section class="cw-metrics"><button @click="tab='providers';status='all'"><span>Providers tracked</span><strong>{{ providerCount }}</strong><small>Across the selected agencies</small></button><button @click="tab='all';status='open'"><span>Open credentialing work</span><strong>{{ openCount }}</strong><small>Applications and verification</small></button><button @click="tab='dates';status='all'"><span>Due within 30 days</span><strong>{{ upcoming.length }}</strong><small>Includes overdue follow-ups</small></button><button @click="tab='payers';status='all'"><span>Payers managed</span><strong>{{ data.payers.length }}</strong><small>Agency-specific payer records</small></button></section>
      <nav class="cw-tabs" aria-label="Credentialing area"><button v-for="item in tabs" :key="item.id" :class="{on:tab===item.id}" @click="tab=item.id;page=1">{{ item.name }}</button></nav>
      <section v-if="tab==='payers'" class="cw-card"><h2>Agency payer connections</h2><p>Map each payer record to its verified electronic payer ID. Credentialing and contracting are separate from claims, ERA, and eligibility enrollment.</p><div class="cw-table"><table><thead><tr><th>Agency</th><th>Payer</th><th>Electronic payer ID</th><th>Credential records</th><th></th></tr></thead><tbody><tr v-for="payer in filteredPayers" :key="`${payer.agencyId}-${payer.id}`"><td>{{ agencyName(payer.agencyId) }}</td><td>{{ payer.name }}</td><td>{{ payer.payerId || 'Not mapped' }}</td><td>{{ data.records.filter(r=>r.agencyId===payer.agencyId && r.payerDefinitionId===payer.id).length }}</td><td><button @click="selectPayer(payer)">Map / review</button></td></tr></tbody></table></div><p v-if="!filteredPayers.length">No matching agency payer definitions. Select an agency and add a payer in its credentialing records.</p></section>
      <div v-else class="cw-main">
        <section class="cw-card"><div class="cw-section-head"><div><h2>{{ tab==='groups' ? 'Agency group NPI tracker' : tab==='dates' ? 'Upcoming dates & follow-ups' : 'Provider & agency credentialing tracker' }}</h2><p>{{ filteredRecords.length }} matching records · active status requires a documented source.</p></div></div><div class="cw-table"><table><thead><tr><th>Provider / group</th><th>Agency</th><th>NPI</th><th>Payer</th><th>Status</th><th>Effective</th><th>Revalidation</th><th>Next action</th><th></th></tr></thead><tbody><tr v-for="record in pagedRecords" :key="recordKey(record)" :class="{selected: selected && recordKey(selected)===recordKey(record)}"><td><strong>{{ record.subjectName }}</strong><small>{{ record.subjectType==='group' ? 'Agency group' : 'Provider' }}</small></td><td>{{ agencyName(record.agencyId) }}</td><td>{{ record.providerNpi || 'Not recorded' }}</td><td>{{ record.payerName }}</td><td><span class="cw-badge" :class="record.status">{{ label(record.status) }}</span></td><td>{{ date(record.effectiveDate) }}</td><td :class="{overdue:isOverdue(record.revalidationDue)}">{{ date(record.revalidationDue) }}</td><td>{{ record.nextAction || 'Review record' }}<small v-if="record.followUpDate">Due {{ date(record.followUpDate) }}</small></td><td><button @click="selectRecord(record)">Review</button></td></tr></tbody></table></div><p v-if="!filteredRecords.length" class="cw-empty">No matching credentialing records. Choose an agency to add providers, payer definitions, or group NPI enrollments.</p><footer class="cw-pagination"><button :disabled="page<=1" @click="page--">Previous</button><span>Page {{ page }} of {{ Math.max(1,Math.ceil(filteredRecords.length/25)) }}</span><button :disabled="page*25>=filteredRecords.length" @click="page++">Next</button></footer></section>
        <aside class="cw-card cw-dates"><h2>Upcoming credentialing dates</h2><button v-for="item in upcoming.slice(0,8)" :key="`${recordKey(item.record)}-${item.type}`" class="cw-date" @click="selectRecord(item.record)"><span :class="{overdue:isOverdue(item.date)}">{{ date(item.date) }}</span><strong>{{ item.type }}</strong><span>{{ item.record.subjectName }}</span><small>{{ agencyName(item.record.agencyId) }} · {{ item.record.payerName }}</small></button><p v-if="!upcoming.length">No recorded follow-ups or revalidations are due within 30 days.</p><small>Dates appear only when recorded. Unrecorded dates are not treated as current.</small></aside>
      </div>
      <section class="cw-card"><h2>Agency directory</h2><div class="cw-agencies"><button v-for="agency in organizations" :key="agency.id" @click="scope=String(agency.id)"><img v-if="agency.logo_url" :src="logoUrl(agency.logo_url)" alt="" /><span><strong>{{ agency.name }}</strong><small>{{ scope==='all' || scope===String(agency.id) ? `${data.records.filter(r=>Number(r.agencyId)===Number(agency.id)).length} credential records` : 'Open agency' }}</small></span><span>→</span></button></div></section>
    </template>
    <div v-if="selected" class="cw-overlay" @click.self="close"><aside ref="drawer" class="cw-drawer" role="dialog" aria-modal="true" aria-labelledby="cw-detail-title" tabindex="-1" @keydown.esc="close" @keydown.tab="trapFocus">
      <header><div><span class="cw-eyebrow">{{ agencyName(selected.agencyId) }}</span><h2 id="cw-detail-title">{{ selected.subjectName || selected.name }}</h2><p>{{ selected.payerName || 'Electronic payer mapping' }}</p></div><button aria-label="Close credential details" @click="close">×</button></header>
      <form @submit.prevent="save"><template v-if="selected.subjectType!=='payer'"><label>Status<select v-model="form.status"><option v-for="item in statuses" :key="item" :value="item">{{ label(item) }}</option></select></label><label v-if="selected.subjectType==='provider'">Billing group NPI<select v-model="form.billingGroupNpiId"><option value="">Not linked</option><option v-for="group in agencyGroups" :key="group.id" :value="group.id">{{ group.npi }} · {{ group.label || group.officeName }}</option></select></label><div class="cw-fields"><label>Revalidation due<input v-model="form.revalidationDue" type="date" /></label><label>Follow-up date<input v-model="form.followUpDate" type="date" /></label></div><label>Next action<textarea v-model="form.nextAction" maxlength="1000" rows="3" /></label></template><label v-else>Verified electronic payer ID<input v-model="form.payerId" required maxlength="32" /></label><label>Evidence / source reference<input v-model="form.evidenceReference" required minlength="5" maxlength="500" placeholder="Payer letter, portal confirmation or dated reference" /></label><p class="cw-help">Record credentialing references here. Patient details and portal passwords belong in their dedicated records.</p><p v-if="saveError" class="cw-error" role="alert">{{ saveError }}</p><button class="primary" :disabled="saving">{{ saving ? 'Saving…' : 'Save credentialing update' }}</button></form>
      <template v-if="selected.subjectType!=='payer'"><section class="cw-detail-section"><h3>Connected payer workflow</h3><p>Group NPI: <strong>{{ selectedGroup?.npi || 'Link an agency group NPI' }}</strong><br />Electronic payer ID: <strong>{{ selectedPayer?.payerId || 'Map this payer in Payers & connections' }}</strong></p><p v-if="selectedGroup?.officeName">{{ selectedGroup.officeName }} · {{ selectedGroup.streetAddress }} {{ selectedGroup.city }}, {{ selectedGroup.state }}</p><dl><div v-for="type in ['1500','era','elig']" :key="type"><dt>{{ {'1500':'Claims enrollment',era:'ERA enrollment',elig:'Eligibility enrollment'}[type] }}</dt><dd>{{ enrollmentStatus(type) }}</dd></div></dl><p v-if="linkedClaims!==null">{{ linkedClaims }} claims linked by agency, electronic payer ID and group NPI{{ selected.subjectType==='provider' ? ', and service provider' : '' }}.</p><p v-else>Claim linkage unavailable. A mapped payer, linked group NPI, and claim tracking are required.</p><ul v-if="claimStatuses.length"><li v-for="[state,count] in claimStatuses" :key="state">{{ state.replaceAll('_',' ') }}: {{ count }}</li></ul><p class="cw-help">Counts contain no patient or financial details. Historical claims without an electronic payer ID are not guessed from payer names. An active credential does not establish an electronic connection.</p><button v-if="selectedAgency?.canViewBilling" @click="openBilling">Open agency billing workspace</button></section></template>
      <button @click="openRecords(selected.agencyId,selected.subjectType==='group'?'group-npis':'payer-credentialing')">Open credential records, documents & contacts</button>
      <section class="cw-detail-section"><h3>Update history</h3><p v-if="historyLoading">Loading history…</p><p v-if="historyError" role="alert">{{ historyError }}</p><ol><li v-for="entry in history" :key="entry.id">{{ date(entry.createdAt) }} · User #{{ entry.actorUserId }}<p>{{ label(entry.changes?.status) || entry.changes?.payerId }} · {{ entry.changes?.evidenceReference }}</p></li></ol><p v-if="!history.length && !historyLoading && !historyError">No workspace updates recorded.</p></section>
    </aside></div>
  </div>
</template>
<script setup>
import {computed,ref,reactive,watch,onBeforeUnmount,nextTick} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {useAgencyStore} from '../../store/agency';
import api from '../../services/api';
import {toUploadsUrl} from '../../utils/uploadsUrl';
const logoUrl=value=>value?(/^\/assets\//.test(value)?value:toUploadsUrl(value)):null;
const route=useRoute(),router=useRouter(),agencyStore=useAgencyStore();
const scope=ref(String(route.query.agencyId || 'all')),search=ref(''),status=ref('all'),tab=ref('all'),page=ref(1);
const empty=()=>({records:[],payers:[],groups:[],enrollments:[],claimCounts:[],capabilities:{}});
const data=ref(empty()),organizations=ref([]),loaded=ref(false),loading=ref(false),error=ref(''),notice=ref('');
const selected=ref(null),saving=ref(false),saveError=ref(''),history=ref([]),historyLoading=ref(false),historyError=ref(''),drawer=ref(null),form=reactive({});let request=0,historyRequest=0,priorFocus=null;
const statuses=['not_started','collecting','submitted','in_review','action_required','active','denied','terminated'];
const tabs=[{id:'all',name:'Overview'},{id:'providers',name:'Providers'},{id:'groups',name:'Agency group NPIs'},{id:'payers',name:'Payers & connections'},{id:'dates',name:'Follow-ups & dates'}];
const names={not_started:'Not started',collecting:'Collecting documents',submitted:'Submitted',in_review:'In review',action_required:'Action needed',active:'Active',denied:'Denied',terminated:'Terminated',verification_needed:'Verify historical effective date'};
const label=value=>names[value] || value || '';
const date=value=>value?String(value).slice(0,10):'—';
const today=new Date().toLocaleDateString('en-CA');const soon=new Date();soon.setDate(soon.getDate()+30);const horizon=soon.toLocaleDateString('en-CA');
const isOverdue=value=>value && date(value)<today;
const agencyName=id=>organizations.value.find(a=>Number(a.id)===Number(id))?.name || 'Agency';
const recordKey=r=>`${r.agencyId}-${r.subjectType}-${r.credentialId}`;
const operatorName=computed(()=>agencyStore.currentAgency?.name || 'Management team');
const selectedAgency=computed(()=>organizations.value.find(a=>Number(a.id)===Number(selected.value?.agencyId)));
const brand=computed(()=>{const agency=organizations.value.find(a=>String(a.id)===scope.value);let colors=agency?.color_palette;try{if(typeof colors==='string')colors=JSON.parse(colors);}catch{colors=null;}return /^#[a-f0-9]{6}$/i.test(colors?.primary || '')?{'--cw-accent':colors.primary}:{};});
const providerCount=computed(()=>new Set(data.value.records.filter(r=>r.subjectType==='provider').map(r=>r.providerId)).size);
const openCount=computed(()=>data.value.records.filter(r=>!['active','terminated'].includes(r.status)).length);
const upcoming=computed(()=>data.value.records.flatMap(record=>[{date:record.revalidationDue,type:'Revalidation',record},{date:record.followUpDate,type:'Follow-up',record}]).filter(item=>item.date && date(item.date)<=horizon).sort((a,b)=>date(a.date).localeCompare(date(b.date))));
const matches=r=>!search.value || [r.subjectName,r.providerNpi,r.payerName,r.name,r.payerId,r.nextAction,agencyName(r.agencyId)].join(' ').toLowerCase().includes(search.value.toLowerCase());
const filteredRecords=computed(()=>data.value.records.filter(r=>matches(r)&&(status.value==='all'||(status.value==='open'?!['active','terminated'].includes(r.status):r.status===status.value))&&(tab.value!=='providers'||r.subjectType==='provider')&&(tab.value!=='groups'||r.subjectType==='group')&&(tab.value!=='dates'||upcoming.value.some(item=>recordKey(item.record)===recordKey(r)))));
const pagedRecords=computed(()=>filteredRecords.value.slice((page.value-1)*25,page.value*25));
const filteredPayers=computed(()=>data.value.payers.filter(matches));
const agencyGroups=computed(()=>data.value.groups.filter(g=>Number(g.agencyId)===Number(selected.value?.agencyId)));
const selectedGroup=computed(()=>agencyGroups.value.find(g=>Number(g.id)===Number(selected.value?.subjectType==='group'?selected.value.groupId:form.billingGroupNpiId)));
const selectedPayer=computed(()=>data.value.payers.find(p=>Number(p.agencyId)===Number(selected.value?.agencyId)&&Number(p.id)===Number(selected.value?.payerDefinitionId)));
const matchingEnrollments=computed(()=>selectedGroup.value && selectedPayer.value?.payerId?data.value.enrollments.filter(e=>Number(e.agencyId)===Number(selected.value.agencyId)&&e.payerId===selectedPayer.value.payerId&&e.groupNpi===selectedGroup.value.npi&&Number(e.officeId)===Number(selectedGroup.value.officeId)):[]);
function enrollmentStatus(type){if(!data.value.capabilities.electronicEnrollment)return 'Tracking unavailable';if(!selectedGroup.value || !selectedPayer.value?.payerId)return 'Link group and payer first';const rows=matchingEnrollments.value.filter(e=>e.type===type);return rows.length?rows.map(e=>`${e.status}${e.lastEventAt?` · ${date(e.lastEventAt)}`:''}`).join('; '):'Not recorded';}
const matchingClaims=computed(()=>!selectedGroup.value || !selectedPayer.value?.payerId || !data.value.capabilities.claimLinkage ? null : data.value.claimCounts.filter(c=>Number(c.agencyId)===Number(selected.value.agencyId)&&c.payerId===selectedPayer.value.payerId&&c.groupNpi===selectedGroup.value.npi&&(selected.value.subjectType==='group'||Number(c.providerId)===Number(selected.value.providerId))));
const linkedClaims=computed(()=>matchingClaims.value?.reduce((sum,c)=>sum+Number(c.count),0) ?? null);
const claimStatuses=computed(()=>Object.entries((matchingClaims.value || []).reduce((out,c)=>{out[c.status]=(out[c.status] || 0)+Number(c.count);return out;},{})));

async function load(){const id=++request;close();data.value=empty();loaded.value=false;error.value='';loading.value=true;try{const response=await api.get('/agencies/credentialing/workspace',{params:{...(scope.value!=='all'?{agencyId:scope.value}:{})}});if(id!==request)return;data.value={...empty(),...response.data};organizations.value=response.data.organizations || [];loaded.value=true;}catch(e){if(id!==request)return;organizations.value=[];error.value=e.response?.data?.error?.message || 'Credentialing workspace could not be loaded.';}finally{if(id===request)loading.value=false;}}
async function open(record){priorFocus=document.activeElement;selected.value=record;saveError.value='';history.value=[];historyError.value='';await nextTick();drawer.value?.focus();const seq=++historyRequest;historyLoading.value=true;try{const response=await api.get(`/agencies/${record.agencyId}/credentialing/workflow/${record.subjectType}/${record.credentialId}/history`);if(seq===historyRequest)history.value=(response.data.items || []).map(item=>({...item,changes:typeof item.changes==='string'?JSON.parse(item.changes):item.changes}));}catch{if(seq===historyRequest)historyError.value='History could not be loaded.';}finally{if(seq===historyRequest)historyLoading.value=false;}}
function selectRecord(record){Object.assign(form,{status:statuses.includes(record.status)?record.status:'in_review',billingGroupNpiId:record.billingGroupNpiId || '',revalidationDue:record.revalidationDue?date(record.revalidationDue):'',followUpDate:record.followUpDate?date(record.followUpDate):'',nextAction:record.nextAction || '',evidenceReference:record.evidenceReference || ''});open(record);}
function selectPayer(payer){Object.assign(form,{payerId:payer.payerId || '',evidenceReference:payer.evidenceReference || ''});open({...payer,subjectType:'payer',credentialId:payer.id});}
function close(){historyRequest++;selected.value=null;history.value=[];historyLoading.value=false;priorFocus?.focus?.();}
function trapFocus(event){const nodes=drawer.value?.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey && (document.activeElement===first||document.activeElement===drawer.value)){event.preventDefault();last.focus();}else if(!event.shiftKey && document.activeElement===last){event.preventDefault();first.focus();}}
async function save(){const record=selected.value,scopeRequest=request;if(!record)return;saving.value=true;saveError.value='';try{await api.patch(`/agencies/${record.agencyId}/credentialing/workflow/${record.subjectType}/${record.credentialId}`,{...form,version:record.version});if(scopeRequest!==request || selected.value!==record)return;notice.value='Credentialing update saved with its source reference and audit history.';await load();}catch(e){if(scopeRequest!==request || selected.value!==record)return;saveError.value=e.response?.data?.error?.message || 'Update could not be saved.';}finally{saving.value=false;}}
function openRecords(agencyId,panel='payer-credentialing'){const prefix=route.params.organizationSlug?`/${route.params.organizationSlug}`:'';router.push({path:`${prefix}/admin/credentialing/records`,query:{agencyId:String(agencyId),panel}});}
function openBilling(){if(!selectedAgency.value?.canViewBilling)return;router.push({name:'BillingWorkspace',query:{agencyId:String(selected.value.agencyId),billingSection:'payers'}});}
watch(scope,()=>{page.value=1;notice.value='';load();},{immediate:true});watch([search,status,tab],()=>{page.value=1;});onBeforeUnmount(()=>{request++;historyRequest++;});
</script>
<style scoped>
.cw{--cw-accent:#1575b8;max-width:1800px;margin:0 auto;padding:28px;background:var(--app-surface-muted, #f5f8fc);color:var(--app-ink, #172b4d);min-height:80vh}.cw-header,.cw-section-head,.cw-buttons,.cw-drawer header{display:flex;align-items:center;justify-content:space-between;gap:14px}.cw h1{font-size:2rem;margin:8px 0}.cw h2{font-size:1.12rem;margin:0 0 12px}.cw h3{font-size:1rem}.cw p{color:var(--app-muted, #596a80);line-height:1.5}.cw-eyebrow{font-size:.76rem;text-transform:uppercase;letter-spacing:.08em;color:var(--app-text-blue,var(--cw-accent));font-weight:700}.cw button,.cw select,.cw input,.cw textarea{font:inherit;border:1px solid var(--app-line, #d6e2ee);border-radius:8px;padding:9px 12px;background:var(--app-surface, #fff);color:var(--app-ink, #203b5c)}.cw button{cursor:pointer}.cw button:disabled{cursor:default;opacity:.5}.cw .primary{background:var(--cw-accent);color:white;border-color:var(--app-text-blue,var(--cw-accent))}.cw-toolbar{display:flex;gap:16px;background:var(--app-surface, white);padding:18px;border-radius:12px;border:1px solid var(--app-line, #e0e9f2);margin:20px 0}.cw label{display:flex;flex-direction:column;gap:6px;font-size:.82rem;font-weight:600}.cw-search{flex:1}.cw-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.cw-metrics button{text-align:left;padding:20px;border-top:3px solid var(--cw-accent)}.cw-metrics strong{display:block;font-size:2rem;margin:8px 0}.cw small{display:block;font-size:.76rem;color:var(--app-muted, #64758a);margin-top:5px}.cw-tabs{display:flex;gap:6px;padding:20px 0;flex-wrap:wrap}.cw-tabs button{background:transparent;border-color:transparent}.cw-tabs .on{color:var(--app-text-blue,var(--cw-accent));border-bottom:3px solid var(--cw-accent);background:var(--app-surface, white)}.cw-main{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:18px}.cw-card{background:var(--app-surface, white);border:1px solid var(--app-line, #dfe8f1);border-radius:12px;padding:20px;margin-bottom:18px;min-width:0}.cw-table{overflow:auto}table{width:100%;text-align:left;border-collapse:collapse;font-size:.8rem}th{background:var(--app-surface-muted, #f0f5fa);color:var(--app-ink, #274363);white-space:nowrap}th,td{padding:13px 9px;border-bottom:1px solid var(--app-line, #e7eef5)}tr.selected{background:var(--app-surface-muted, #eef6fd)}.cw-badge{display:inline-block;background:var(--app-surface-muted, #edf1f6);color:var(--app-muted, #4b5e75);border-radius:6px;padding:5px 7px;white-space:nowrap}.cw-badge.active{background:var(--app-tint-green, #dcf7e9);color:var(--app-text-green, #087748)}.cw-badge.action_required,.cw-badge.denied,.cw-badge.terminated{background:var(--app-surface-muted, #ffeaed);color:var(--app-text-red, #b6223b)}.cw-badge.submitted,.cw-badge.in_review,.cw-badge.verification_needed{background:var(--app-tint-amber, #fff3d8);color:var(--app-text-red, #94610b)}.cw-pagination{display:flex;align-items:center;justify-content:flex-end;gap:14px;margin-top:16px;font-size:.8rem}.cw-date{display:flex;flex-direction:column;gap:5px;width:100%;text-align:left;margin:10px 0}.cw .overdue{color:var(--app-text-red, #c02e43)}.cw-agencies{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.cw-agencies button{display:flex;align-items:center;justify-content:space-between;gap:12px;text-align:left}.cw-agencies img{width:38px;height:38px;object-fit:contain}.cw-overlay{position:fixed;inset:0;background:#11253b60;z-index:120;display:flex;justify-content:flex-end}.cw-drawer{background:var(--app-surface, white);width:min(520px,100%);overflow:auto;padding:26px;box-shadow:-8px 0 30px #18304420}.cw-drawer form{display:grid;gap:15px;margin:20px 0}.cw-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.cw-detail-section{border-top:1px solid var(--app-line, #e0e8f1);margin:22px 0;padding-top:14px}.cw-detail-section dl div{display:flex;justify-content:space-between;gap:16px;margin:12px 0;font-size:.83rem}.cw-detail-section dd{margin:0;text-align:right}.cw-help{font-size:.78rem}.cw-error{background:var(--app-surface-muted, #fff0f1);color:var(--app-text-red, #ad273d)!important;padding:12px;border-radius:8px}.cw-notice{background:var(--app-surface-muted, #e4f6ee);padding:12px;border-radius:8px}.cw-empty{padding:25px;text-align:center}@media(max-width:1100px){.cw-main{grid-template-columns:1fr}.cw-dates{display:none}}@media(max-width:650px){.cw{padding:14px}.cw-header,.cw-toolbar{align-items:stretch;flex-direction:column}.cw-metrics{grid-template-columns:1fr 1fr}.cw-fields{grid-template-columns:1fr}}
</style>
